#include "stdlib/stats/base/dists/beta/logcdf.h"
#include "stdlib/math/base/assert/is_nan.h"
#include "stdlib/math/base/special/betainc.h"
#include "stdlib/math/base/special/ln.h"
#include <stdbool.h>

/**
* Evaluates the natural logarithm of the cumulative distribution function (CDF) for a beta distribution.
*
* @param x        input value
* @param alpha    first shape parameter
* @param beta     second shape parameter
* @return         evaluated logCDF
*
* @example
* double y = stdlib_base_dists_beta_logcdf( 0.5, 1.0, 1.0 );
* // returns ~-0.693
*/
double stdlib_base_dists_beta_logcdf( const double x, const double alpha, const double beta ) {
	if (
		stdlib_base_is_nan( x ) ||
		stdlib_base_is_nan( alpha ) ||
		stdlib_base_is_nan( beta ) ||
		alpha <= 0.0 ||
		beta <= 0.0
	) {
		return 0.0 / 0.0; // NaN
	}
	if ( x <= 0.0 ) {
		return -1.0 / 0.0; // -Infinity
	}
	if ( x >= 1.0 ) {
		return 0.0;
	}
	return stdlib_base_ln( stdlib_base_betainc( x, alpha, beta, true, false ) );
}
